from pathlib import Path


def _reject_nonfinite(node):
    if isinstance(node, bool):
        return
    if isinstance(node, float):
        if not math.isfinite(node):
            raise ValueError('non-finite number in payload')
    elif isinstance(node, dict):
        for value in node.values():
            _reject_nonfinite(value)
    elif isinstance(node, list):
        for value in node:
            _reject_nonfinite(value)


def load_payload(path):
    def _bad_const(token):
        raise ValueError('non-finite constant: %s' % token)

    text = Path(path).read_text(encoding='utf-8')
    obj = json.loads(text, parse_constant=_bad_const)
    _reject_nonfinite(obj)
    if not isinstance(obj, (dict, list)):
        raise ValueError('top-level payload must be object or array')
    return obj

