_POLICY_VALUES = ('drop_conflicts', 'first')


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {'name', 'result'}:
        return payload['result']
    return payload


def _reject_nonfinite(node):
    if isinstance(node, bool):
        return
    if isinstance(node, float):
        if not math.isfinite(node):
            raise ValueError('non-finite number in payload')
    elif isinstance(node, dict):
        for value in node.values():
            _reject_nonfinite(value)
    elif isinstance(node, list):
        for value in node:
            _reject_nonfinite(value)


def _is_finite_number(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x)


def _check_call(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError('payloads must be a list')
    if not isinstance(contract, dict):
        raise ValueError('contract must be an object')
    for key in ('name', 'inputs'):
        if key not in contract:
            raise ValueError('contract missing %s' % key)
    if not isinstance(contract['name'], str) or not contract['name'].strip():
        raise ValueError('contract name must be a non-empty string')
    inputs = contract['inputs']
    if not isinstance(inputs, list) or not all(isinstance(x, str) for x in inputs):
        raise ValueError('contract inputs must be a list of strings')
    if len(payloads) != len(inputs):
        raise ValueError('payload count does not match contract inputs')
    for payload in payloads:
        _reject_nonfinite(payload)


def _validate_segment(payload):
    if not isinstance(payload, dict):
        raise ValueError('segment input must be an object')
    for key in ('columns', 'pieces', 'attribute_policy'):
        if key not in payload:
            raise ValueError('segment input missing %s' % key)
    columns = payload['columns']
    if not isinstance(columns, list):
        raise ValueError('columns must be a list')
    seen_columns = set()
    for column in columns:
        if not isinstance(column, str) or not column.strip():
            raise ValueError('column names must be non-empty strings')
        if column in seen_columns:
            raise ValueError('duplicate column name: %r' % column)
        seen_columns.add(column)
    policy = payload['attribute_policy']
    if not isinstance(policy, str) or policy not in _POLICY_VALUES:
        raise ValueError('attribute_policy must be drop_conflicts or first')
    pieces = payload['pieces']
    if not isinstance(pieces, list):
        raise ValueError('pieces must be a list')
    piece_ids = set()
    all_coords = set()
    for piece in pieces:
        if not isinstance(piece, dict):
            raise ValueError('piece must be an object')
        for key in ('id', 'coordinates', 'data', 'attrs'):
            if key not in piece:
                raise ValueError('piece missing %s' % key)
        pid = piece['id']
        if not isinstance(pid, str) or not pid.strip():
            raise ValueError('piece id must be a non-empty string')
        if pid in piece_ids:
            raise ValueError('duplicate piece id: %r' % pid)
        piece_ids.add(pid)
        coords = piece['coordinates']
        data = piece['data']
        if not isinstance(coords, list) or not isinstance(data, list):
            raise ValueError('coordinates and data must be lists')
        if len(coords) != len(data):
            raise ValueError('coordinates and data lengths differ for piece %r' % pid)
        local = set()
        for coord in coords:
            if not _is_finite_number(coord):
                raise ValueError('coordinates must be finite numbers')
            if coord in local or coord in all_coords:
                raise ValueError('duplicate or overlapping coordinate: %r' % coord)
            local.add(coord)
            all_coords.add(coord)
        for row in data:
            if not isinstance(row, list) or len(row) != len(columns):
                raise ValueError('data row width must equal columns length')
            for value in row:
                if not _is_finite_number(value):
                    raise ValueError('data values must be finite numbers')
        if not isinstance(piece['attrs'], dict):
            raise ValueError('piece attrs must be an object')
    return payload


def transform(payloads, contract):
    _check_call(payloads, contract)
    if len(payloads) != 1:
        raise ValueError('segment_index expects exactly one input')
    payload = _validate_segment(_unwrap(payloads[0]))
    order = []
    for piece in payload['pieces']:
        pid = piece['id']
        for row, coord in enumerate(piece['coordinates']):
            order.append({'coordinate': coord, 'piece': pid, 'row': row})
    order.sort(key=lambda entry: entry['coordinate'])
    result = {'columns': list(payload['columns']), 'order': order}
    return {'name': contract['name'], 'result': result}

import json
from pathlib import Path

from model import load_payload
from transform import transform


def _safe_rel(p):
    if not isinstance(p, str) or not p.strip():
        raise ValueError('path must be a non-empty string')
    if p.startswith('/') or '\\' in p or ':' in p:
        raise ValueError('unsafe path: %r' % p)
    parts = p.split('/')
    if any(seg in ('', '.', '..') for seg in parts):
        raise ValueError('unsafe path segment in %r' % p)
    return p


def _read_contract(contract_path):
    contract = load_payload(contract_path)
    if not isinstance(contract, dict):
        raise ValueError('contract must be an object')
    for key in ('name', 'inputs', 'output'):
        if key not in contract:
            raise ValueError('contract missing %s' % key)
    if not isinstance(contract['name'], str) or not contract['name'].strip():
        raise ValueError('contract name must be a non-empty string')
    if not isinstance(contract['inputs'], list):
        raise ValueError('contract inputs must be a list')
    if not isinstance(contract['output'], str):
        raise ValueError('contract output must be a string')
    return contract


def build_component(root, contract_path):
    root = Path(root)
    contract_path = Path(contract_path)
    contract = _read_contract(contract_path)
    inputs = [_safe_rel(x) for x in contract['inputs']]
    output = _safe_rel(contract['output'])
    payloads = [load_payload(root / x) for x in inputs]
    result = transform(payloads, contract)
    out_path = root / output
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(result, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + '\n',
        encoding='utf-8')
    return result


def _infer_root(contract_path, inputs):
    here = contract_path.resolve().parent
    for ancestor in [here] + list(here.parents):
        if all((ancestor / x).is_file() for x in inputs):
            return ancestor
    raise ValueError('cannot locate workspace root containing all inputs')


if __name__ == '__main__':
    _cp = Path(__file__).resolve().with_name('contract.json')
    _contract = _read_contract(_cp)
    _inputs = [_safe_rel(x) for x in _contract['inputs']]
    build_component(_infer_root(_cp, _inputs), _cp)

