import json
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _safe_rel(p):
    if not isinstance(p, str) or not p.strip():
        raise ValueError('path must be a non-empty string')
    if p.startswith('/') or '\\' in p or ':' in p:
        raise ValueError('unsafe path: %r' % p)
    parts = p.split('/')
    if any(seg in ('', '.', '..') for seg in parts):
        raise ValueError('unsafe path segment in %r' % p)
    return p


def _load_contracts():
    contracts = []
    for cp in sorted(ROOT.rglob('contract.json')):
        if 'outputs' in cp.relative_to(ROOT).parts:
            continue
        contract = json.loads(cp.read_text(encoding='utf-8'))
        if not isinstance(contract, dict):
            raise ValueError('bad contract at %s' % cp)
        for key in ('name', 'inputs', 'output'):
            if key not in contract:
                raise ValueError('contract missing %s at %s' % (key, cp))
        if not isinstance(contract['name'], str) or not contract['name'].strip():
            raise ValueError('bad contract name at %s' % cp)
        if not isinstance(contract['inputs'], list):
            raise ValueError('bad contract inputs at %s' % cp)
        for x in contract['inputs']:
            _safe_rel(x)
        _safe_rel(contract['output'])
        contracts.append((cp, contract))
    if not contracts:
        raise ValueError('no contracts found')
    names = [c['name'] for _, c in contracts]
    if len(set(names)) != len(names):
        raise ValueError('duplicate component names')
    outputs = [c['output'] for _, c in contracts]
    if len(set(outputs)) != len(outputs):
        raise ValueError('duplicate component outputs')
    return contracts


def _topological_order(contracts):
    out_to_name = {c['output']: c['name'] for _, c in contracts}
    info = {c['name']: (cp, c) for cp, c in contracts}
    remaining = {}
    for _, c in contracts:
        deps = set()
        for x in c['inputs']:
            if x in out_to_name and out_to_name[x] != c['name']:
                deps.add(out_to_name[x])
        remaining[c['name']] = deps
    ordered = []
    while remaining:
        ready = sorted(name for name, deps in remaining.items() if not deps)
        if not ready:
            raise ValueError('dependency cycle among components')
        for name in ready:
            ordered.append(name)
            del remaining[name]
        for deps in remaining.values():
            deps.difference_update(ready)
    return [info[name] for name in ordered]


def _run(args):
    proc = subprocess.run(args, cwd=str(ROOT))
    if proc.returncode != 0:
        sys.exit(proc.returncode if proc.returncode != 0 else 1)


def main():
    out_dir = ROOT / 'outputs'
    if out_dir.is_symlink():
        out_dir.unlink()
    elif out_dir.exists():
        shutil.rmtree(out_dir)
    contracts = _topological_order(_load_contracts())
    for cp, contract in contracts:
        script = cp.with_name('render.py')
        if not script.is_file():
            raise ValueError('missing render.py for component %s' % contract['name'])
        _run([sys.executable, str(script)])
    for helper in ('integrate.py', 'final_report.py'):
        helper_path = ROOT / helper
        if not helper_path.is_file():
            raise ValueError('missing %s' % helper)
        _run([sys.executable, str(helper_path)])


if __name__ == '__main__':
    main()

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
TITLE = '单变化轴的数据分片拼接'
FALSE_KEYS = ('complete', 'checkout', 'committed', 'ok')
NONEMPTY_KEYS = ('unavailable', 'missing', 'conflicts', 'unreachable')


def _attention(components):
    hits = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get('blocked') is True:
            hits.add(name)
        for key in FALSE_KEYS:
            if result.get(key) is False:
                hits.add(name)
        for key in NONEMPTY_KEYS:
            if key not in result:
                continue
            value = result[key]
            if value is None:
                continue
            if isinstance(value, (str, list, dict, tuple, set)):
                if len(value) > 0:
                    hits.add(name)
            elif value:
                hits.add(name)
    return sorted(hits)


def main():
    core = json.loads((ROOT / 'outputs' / 'core_manifest.json').read_text(encoding='utf-8'))
    if not isinstance(core, dict) or set(core) != {'components'}:
        raise ValueError('core manifest must contain exactly components')
    components = core['components']
    if not isinstance(components, dict):
        raise ValueError('components must be an object')
    blob = json.dumps(core, ensure_ascii=False, sort_keys=True,
                      separators=(',', ':'), allow_nan=False).encode('utf-8')
    report = {
        'title': TITLE,
        'component_count': len(components),
        'sha256': hashlib.sha256(blob).hexdigest(),
        'attention': _attention(components),
    }
    out_path = ROOT / 'outputs' / 'final_report.json'
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + '\n',
        encoding='utf-8')


if __name__ == '__main__':
    main()

